                <input type="text" class="form-control" id="endereco" name="endereco" readonly>
            </div>
            <div class="form-group">
                <label for="apelido">Apelido:</label>
                <input type="text" class="form-control" id="apelido" name="apelido">
            </div>
            <button type="submit" class="btn btn-primary">Cadastrar</button>
        </form>
    </div>
    <script>
        $("#cep").on("change", function() {
            var cep = $(this).val();
            if (cep.length == 8) {
                $.getJSON("https://viacep.com.br/ws/"+ cep +"/json/", function(data) {
                    if (!("erro" in data)) {
                        $("#endereco").val(data.logradouro + ", " + data.bairro + ", " + data.localidade + " - " + data.uf);
                    } else {
                        $("#endereco").val("");
                        alert("CEP não encontrado");
                    }
                });
            } else {
                $("#endereco").val("");
            }
        });
    </script>
</body>
</html>
```

Em seguida, crie um arquivo chamado "cadastro.php":

```php
<?php

$servername = "localhost";
$username = "username";
$password = "password";
$dbname = "my_database";

// Cria a conexão com o banco de dados
$conn = new mysqli($servername, $username, $password, $dbname);

// Verifica a conexão
if ($conn->connect_error) {
    die("Conexão falhou: " . $conn->connect_error);
}

$nome = $_POST["nome"];
$cpf = $_POST["cpf"];
$data_nascimento = $_POST["data_nascimento"];
$telefone = $_POST["telefone"];
$cep = $_POST["cep"];
$endereco = $_POST["endereco"];
$apelido = $_POST["apelido"];

$sql = "INSERT INTO clientes (nome, cpf, data_nascimento, telefone, cep, endereco, apelido) VALUES ('$nome', '$cpf', '$data_nascimento', '$telefone', '$cep', '$endereco', '$apelido')";

if ($conn->query($sql) === TRUE) {
    echo "Cliente cadastrado com sucesso!";
} else {
    echo "Erro: " . $sql . "<br>" . $conn->error;
}

$conn->close();

?>
```

Lembre-se de substituir "username", "password" e "my_database" pelas informações de acesso do seu banco de dados.

Este exemplo utiliza Bootstrap 4 para estilização, jQuery para manipulação de DOM e chamadas AJAX e a API ViaCEP (https://viacep.com.br/) para obter o endereço pelo CEP.

